  5293  static int
  5294  md_end_current_block(MD_CTX* ctx)
  5295  {
  5296      int ret = 0;
  5297
  5298      if(ctx->current_block == NULL)
  5299          return ret;
  5300
  5301      /* Check whether there is a reference definition. (We do this here instead
  5302       * of in md_analyze_line() because reference definition can take multiple
  5303       * lines.) */
  5304      if(ctx->current_block->type == MD_BLOCK_P  ||
  5305         (ctx->current_block->type == MD_BLOCK_H  &&  (ctx->current_block->flags & MD_BLOCK_SETEXT_HEADER)))
  5306      {
  5307          MD_LINE* lines = (MD_LINE*) (ctx->current_block + 1);
  5308          if(lines[0].beg < ctx->size  &&  CH(lines[0].beg) == _T('[')) {
  5309              MD_CHECK(md_consume_link_reference_definitions(ctx));
  5310              if(ctx->current_block == NULL)
  5311                  return ret;
  5312          }
  5313      }
  5314
  5315      if(ctx->current_block->type == MD_BLOCK_H  &&  (ctx->current_block->flags & MD_BLOCK_SETEXT_HEADER)) {
  5316          MD_SIZE n_lines = ctx->current_block->n_lines;
  5317
  5318          if(n_lines > 1) {
  5319              /* Get rid of the underline. */
  5320              ctx->current_block->n_lines--;
  5321              ctx->n_block_bytes -= sizeof(MD_LINE);
  5322          } else {
  5323              /* Only the underline has left after eating the ref. defs.
  5324               * Keep the line as beginning of a new ordinary paragraph. */
  5325              ctx->current_block->type = MD_BLOCK_P;
  5326              return 0;
  5327          }
  5328      }
  5329
  5330      /* Mark we are not building any block anymore. */
  5331      ctx->current_block = NULL;
  5332
  5333  abort:
  5334      return ret;
  5335  }
