  5337  static int
  5338  md_add_line_into_current_block(MD_CTX* ctx, const MD_LINE_ANALYSIS* analysis)
  5339  {
  5340      MD_ASSERT(ctx->current_block != NULL);
  5341
  5342      if(ctx->current_block->type == MD_BLOCK_CODE || ctx->current_block->type == MD_BLOCK_HTML) {
  5343          MD_VERBATIMLINE* line;
  5344
  5345          line = (MD_VERBATIMLINE*) md_push_block_bytes(ctx, sizeof(MD_VERBATIMLINE));
  5346          if(line == NULL)
  5347              return -1;
  5348
  5349          line->indent = analysis->indent;
  5350          line->beg = analysis->beg;
  5351          line->end = analysis->end;
  5352      } else {
  5353          MD_LINE* line;
  5354
  5355          line = (MD_LINE*) md_push_block_bytes(ctx, sizeof(MD_LINE));
  5356          if(line == NULL)
  5357              return -1;
  5358
  5359          line->beg = analysis->beg;
  5360          line->end = analysis->end;
  5361      }
  5362      ctx->current_block->n_lines++;
  5363
  5364      return 0;
  5365  }
